<div class="auth-wrap"><div><div class="eyebrow">YOUR BUSINESS BELONGS HERE</div><h1><?= match($mode){'login'=>'Welcome back.','register'=>'Let’s grow together.','forgot'=>'Reset your password.','reset'=>'A fresh start.'} ?></h1><p>One workspace for your wholesale business.</p></div><form method="post" action="/<?= e($mode) ?>" class="panel auth-form"><?= csrf() ?>
